import {computePosition,offset,flip,shift} from '@floating-ui/dom';
export function el(tag,cls='',text=''){const e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e}
export function icon(name,cls=''){const i=el('img','ui-icon '+cls);i.src=`ui/icons/${name}.svg`;i.alt='';i.setAttribute('aria-hidden','true');return i}
export function button(text,fn,{kind='',icon:ico,disabled=false,tip}={}){const b=el('button',`ui-button ${kind}`);b.type='button';b.setAttribute('aria-label',text);if(ico)b.append(icon(ico));b.append(el('span','',text));b.disabled=disabled;b.onclick=fn;if(tip)tooltip(b,tip);return b}
export function ornament(){const x=el('img','ornament');x.src='ui/textures/ornament.svg';x.alt='';return x}
export function tooltip(anchor,content){const tip=document.getElementById('tooltip');const show=async()=>{tip.textContent=content;tip.hidden=false;anchor.setAttribute('aria-describedby','tooltip');const p=await computePosition(anchor,tip,{placement:'top',strategy:'fixed',middleware:[offset(12),flip(),shift({padding:16})]});Object.assign(tip.style,{left:p.x+'px',top:p.y+'px'})};const hide=()=>{tip.hidden=true;anchor.removeAttribute('aria-describedby')};anchor.addEventListener('mouseenter',show);anchor.addEventListener('focus',show);anchor.addEventListener('mouseleave',hide);anchor.addEventListener('blur',hide)}
export function modal(title,{wide=false,onClose,canClose=()=>true}={}){const previous=document.activeElement,d=el('dialog','ui-modal ornamented'+(wide?' wide':'')),head=el('header','modal-heading');head.append(el('h2','',title),button('×',()=>{if(canClose())d.close()},{kind:'icon-button',tip:'Fechar janela'}));d.append(head,ornament());const body=el('div','modal-content');d.append(body);document.getElementById('overlays').append(d);d.addEventListener('cancel',e=>{if(!canClose())e.preventDefault()});d.addEventListener('close',()=>{d.remove();previous?.focus();onClose?.()});d.addEventListener('click',e=>{if(e.target===d&&canClose()){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.showModal();return {dialog:d,body}}
export function meter(value,max,label,cls=''){const box=el('div','meter '+cls),text=el('div','meter-label');text.append(el('span','',label),el('span','',`${value} / ${max}`));const track=el('div','meter-track'),fill=el('div','meter-fill');fill.style.width=Math.max(0,Math.min(100,value/max*100))+'%';track.append(fill);track.setAttribute('role','meter');track.setAttribute('aria-label',label);track.setAttribute('aria-valuenow',value);track.setAttribute('aria-valuemin','0');track.setAttribute('aria-valuemax',max);box.append(text,track);return box}
export function choice(text,n,fn){const b=el('button','dialogue-choice');b.append(el('span','choice-number',String(n)+'.'),el('span','',text));b.onclick=fn;return b}
export function die(number='20',sides=20){const b=el('div','die');b.setAttribute('aria-label',`Dado de ${sides} lados`);b.innerHTML='<svg viewBox="0 0 220 240" aria-hidden="true"><defs><linearGradient id="dieFace" x2="1" y2="1"><stop stop-color="#a84f3e"/><stop offset=".45" stop-color="#5f1f28"/><stop offset="1" stop-color="#220e1c"/></linearGradient></defs><path d="M110 5 205 62v116l-95 57-95-57V62Z" fill="url(#dieFace)" stroke="#d0ad70" stroke-width="3"/><path d="M110 5 62 82l-47-20m95-57 48 77 47-20M62 82h96l-48 85ZM15 178l47-96 48 153 48-153 47 96-95-11Z" fill="none" stroke="#d7a96b" stroke-opacity=".55" stroke-width="2"/></svg>';b.append(el('strong','die-number',String(number)));return b}
