import {el,button,ornament} from './ui.js';
import {WORDS,CODES,GIVEN,HINTS,normalizeLetter,evaluateGate} from '../Utilities/cryptogram.cjs';
import './cryptogram.css';
export function renderGateTutorial(stage,{onStart}){stage.classList.add('gate-stage');const panel=el('section','gate-panel gate-tutorial');panel.setAttribute('aria-labelledby','gate-title');const title=el('h2','','O selo do portão');title.id='gate-title';panel.append(el('p','eyebrow','ANTES DE DECIFRAR'),title,ornament(),el('p','','Cada número representa uma letra. Números iguais sempre recebem a mesma letra; números diferentes recebem letras diferentes.'),el('p','','Por exemplo, se 4 = A e 9 = S, a sequência 4 · 9 · 4 forma ASA. Este exemplo não é a chave do portão.'),el('p','','Preencha as letras nas casas. As repetições serão completadas juntas. As letras A e E já estão gravadas na pedra; os espaços separam as palavras.'),el('p','','Ao terminar, confira a inscrição e escolha como usar sua mensagem para abrir a passagem. Se precisar, há três dicas, sem limite de tentativas.'),el('p','gate-banter','Gale: “Uma cifra por substituição. Finalmente, uma porta disposta a receber uma resposta por escrito.”'),button('Entendi. Examinar o criptograma',onStart,{kind:'primary'}));stage.append(panel)}
export function renderCryptogram(stage,{gate,onSave,onOpen,onSound,onTutorial}){stage.classList.add('gate-stage');const panel=el('section','gate-panel');panel.setAttribute('aria-labelledby','gate-title');const title=el('h2','','A inscrição cifrada');title.id='gate-title';const feedback=el('p','gate-feedback');feedback.setAttribute('role','status');feedback.setAttribute('aria-live','polite');feedback.tabIndex=-1;
 const report=text=>{feedback.textContent=text};
 panel.append(el('p','eyebrow','PORTÃO DO CASTELO'),title,ornament());
 if(gate.solved){panel.append(el('p','','A luz percorre a pedra e revela a passagem. O mecanismo cede.'),el('p','gate-banter','Karlach: “Uma porta que abre com fogo sem precisar pegar fogo. Gostei. Um pouco decepcionante, mas gostei.”'),button('Atravessar o portão',onOpen,{kind:'primary'}));stage.append(panel);return}
 if(gate.decoded){panel.append(el('p','gate-solution','A LUZ DA TOCHA REVELA A PASSAGEM'),el('p','','O selo aguarda uma ação. Como você interpreta a inscrição?'));const actions=el('div','gate-actions');actions.append(button('Erguer a tocha diante do selo',()=>{gate.solved=true;onSave();onSound('discovery');renderAgain()},{kind:'primary'}),button('Encostar o astrolábio na fechadura',()=>{onSound('failure');report('A fechadura não reage. Gale recolhe o astrolábio: “Depois do que passamos para recuperar isso, prefiro não usá-lo como chave de fenda.”')}),button('Pedir para Karlach empurrar',()=>{onSound('failure');report('A pedra não cede. Karlach cruza os braços: “Tá. A porta quer que eu leia. Sempre tem uma exigência absurda.”')}));panel.append(actions,feedback);stage.append(panel);return}
 panel.append(el('p','gate-intro','Decifre a mensagem gravada na pedra. Uma letra escolhida preenche todas as ocorrências daquele número.'));
 const form=el('form','cryptogram-form'),board=el('div','cryptogram-board');board.setAttribute('role','group');board.setAttribute('aria-label','Mensagem cifrada');const fields=[];
 for(const [wordIndex,word]of WORDS.entries()){const group=el('div','cipher-word');group.setAttribute('role','group');group.setAttribute('aria-label',`Palavra ${wordIndex+1}, ${word.length} letras`);for(const [index,code]of word.entries()){const cell=el('label','cipher-cell'+(GIVEN[code]?' given':'')),number=el('span','cipher-number',String(code)),input=el('input','cipher-letter');input.type='text';input.autocomplete='off';input.spellcheck=false;input.inputMode='text';input.maxLength=1;input.value=GIVEN[code]||gate.entries[code]||'';input.dataset.code=String(code);input.setAttribute('aria-label',`Palavra ${wordIndex+1}, letra ${index+1}, número ${code}${GIVEN[code]?', letra '+GIVEN[code]+' já gravada':''}`);if(GIVEN[code]){input.readOnly=true;input.tabIndex=-1}else{input.oninput=()=>{const letter=normalizeLetter(input.value);if(letter&&CODES.some(other=>other!==code&&(GIVEN[other]||gate.entries[other])===letter)){input.value=gate.entries[code]||'';report(`A letra ${letter} já pertence a outro número. Apague a associação anterior para trocá-la.`);return}gate.entries[code]=letter;for(const field of fields)if(field.dataset.code===String(code))field.value=letter;onSave();report('');updateKey()};}fields.push(input);cell.append(number,input);group.append(cell)}board.append(group)}
 const key=el('div','cipher-key');key.setAttribute('aria-label','Suas associações de números e letras');const updateKey=()=>{key.replaceChildren();for(const code of CODES)key.append(el('span','',`${code} = ${GIVEN[code]||gate.entries[code]||'—'}`))};updateKey();
 const controls=el('div','gate-controls');const check=button('Conferir inscrição',()=>{},{kind:'primary'});check.type='submit';controls.append(check,button('Dica',()=>{gate.hints=Math.min(3,gate.hints+1);onSave();renderAgain()}),button('Limpar minhas letras',()=>{gate.entries={...GIVEN};onSave();renderAgain()},{kind:'ghost'}),button('Rever orientação',onTutorial,{kind:'ghost'}));form.onsubmit=e=>{e.preventDefault();const status=evaluateGate(gate.entries);if(status==='solved'){gate.decoded=true;onSave();onSound('success');renderAgain();return}gate.attempts++;onSave();onSound('failure');report(status==='incomplete'?'Ainda há letras em branco. Você pode conferir suas associações abaixo.':status==='conflict'?'Uma letra está ligada a números diferentes. Cada número precisa da sua própria letra.':'A inscrição ainda não faz sentido. Reveja as palavras; suas letras foram mantidas.');feedback.focus()};form.append(board,key,controls,feedback);panel.append(form);if(gate.hints){const hints=el('aside','gate-hints');hints.setAttribute('aria-label','Dicas reveladas');for(let i=0;i<gate.hints;i++)hints.append(el('p','',`Dica ${i+1}: ${HINTS[i]}`));panel.append(hints)}stage.append(panel);
 function renderAgain(){panel.remove();renderCryptogram(stage,{gate,onSave,onOpen,onSound,onTutorial})}
}
